'use client'

export type NavigationDirection = 'forward' | 'back'

let resolveNavigation: (() => void) | null = null

export function navigationCommitted() {
  resolveNavigation?.()
  resolveNavigation = null
}

export function canAnimateNavigation() {
  return (
    typeof document !== 'undefined' &&
    typeof document.startViewTransition === 'function' &&
    !window.matchMedia('(prefers-reduced-motion: reduce)').matches
  )
}

export function startNavigationTransition(
  navigate: () => void,
  direction: NavigationDirection = 'forward'
) {
  if (!canAnimateNavigation()) {
    navigate()
    return
  }

  document.documentElement.dataset.navDirection = direction

  const transition = document.startViewTransition(() => {
    navigate()
    return new Promise<void>((resolve) => {
      resolveNavigation = resolve
      setTimeout(() => {
        if (resolveNavigation === resolve) resolveNavigation = null
        transition.skipTransition()
      }, 600)
    })
  })

  const clearDirection = () => {
    delete document.documentElement.dataset.navDirection
  }
  transition.finished.then(clearDirection, clearDirection)
}

'use client'

import { usePathname } from 'next/navigation'
import { useEffect } from 'react'
import { navigationCommitted } from './view-transition'

export function NavigationEvents() {
  const pathname = usePathname()

  useEffect(() => {
    navigationCommitted()
  }, [pathname])

  return null
}

'use client'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import type { ComponentProps, MouseEvent } from 'react'
import {
  startNavigationTransition,
  type NavigationDirection,
} from './view-transition'

type TransitionLinkProps = ComponentProps<typeof Link> & {
  direction?: NavigationDirection
  prepare?: (anchor: HTMLAnchorElement) => void
}

export function TransitionLink({
  direction = 'forward',
  prepare,
  onClick,
  href,
  ...rest
}: TransitionLinkProps) {
  const router = useRouter()

  const handleClick = (e: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(e)
    if (e.defaultPrevented) return
    if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey)
      return

    e.preventDefault()
    prepare?.(e.currentTarget)
    startNavigationTransition(
      () => router.push(typeof href === 'string' ? href : href.toString()),
      direction
    )
  }

  return <Link {...rest} href={href} onClick={handleClick} />
}

'use client'

import { useEffect, useRef } from 'react'

export const LAST_VIEWED_PRODUCT_KEY = 'vt:last-product'

export function productImageTransitionName(slug: string) {
  return `product-image-${slug}`
}

export function ProductImage({
  slug,
  color,
}: {
  slug: string
  color: string
}) {
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    try {
      if (sessionStorage.getItem(LAST_VIEWED_PRODUCT_KEY) === slug) {
        el.style.setProperty(
          'view-transition-name',
          productImageTransitionName(slug)
        )
        return () => {
          el.style.removeProperty('view-transition-name')
        }
      }
    } catch {}
  }, [slug])

  return (
    <div
      ref={ref}
      className="product-image"
      style={{ backgroundColor: color }}
    />
  )
}

'use client'

import type { Product } from '@/lib/products'
import { TransitionLink } from './TransitionLink'
import {
  LAST_VIEWED_PRODUCT_KEY,
  ProductImage,
  productImageTransitionName,
} from './ProductImage'

export function ProductCard({ product }: { product: Product }) {
  const prepare = (anchor: HTMLAnchorElement) => {
    document
      .querySelectorAll<HTMLElement>('.product-image')
      .forEach((el) => el.style.removeProperty('view-transition-name'))
    anchor
      .querySelector<HTMLElement>('.product-image')
      ?.style.setProperty(
        'view-transition-name',
        productImageTransitionName(product.slug)
      )
    try {
      sessionStorage.setItem(LAST_VIEWED_PRODUCT_KEY, product.slug)
    } catch {}
  }

  return (
    <TransitionLink
      href={`/product/${product.slug}`}
      className="product-card"
      direction="forward"
      prepare={prepare}
    >
      <ProductImage slug={product.slug} color={product.color} />
      <h2>{product.name}</h2>
      <p>${product.price}</p>
    </TransitionLink>
  )
}

import { products } from '@/lib/products'
import { ProductCard } from './ProductCard'

export function ProductGrid() {
  return (
    <div className="product-grid animate-in">
      {products.map((product) => (
        <ProductCard key={product.slug} product={product} />
      ))}
    </div>
  )
}

import { Suspense } from 'react'
import { getProduct, products } from '@/lib/products'
import { notFound } from 'next/navigation'
import { TransitionLink } from '../../TransitionLink'

async function ProductDetails({ slug }: { slug: string }) {
  await new Promise((resolve) => setTimeout(resolve, 100))
  const product = getProduct(slug)
  if (!product) notFound()

  return (
    <div className="product-info animate-in">
      <h1>{product.name}</h1>
      <p className="product-price">${product.price}</p>
      <p className="product-description">{product.description}</p>
    </div>
  )
}

function DetailsSkeleton() {
  return (
    <div className="product-info">
      <div className="skeleton-text large" />
      <div className="skeleton-text short" />
      <div className="skeleton-text" />
    </div>
  )
}

export default async function ProductPage({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  const product = products.find((p) => p.slug === slug)
  if (!product) notFound()

  return (
    <div>
      <TransitionLink href="/" className="back-link" direction="back">
        ← Back to products
      </TransitionLink>
      <div className="product-detail">
        <div
          className="product-hero"
          style={{
            backgroundColor: product.color,
            viewTransitionName: `product-image-${product.slug}`,
          }}
        />
        <Suspense fallback={<DetailsSkeleton />}>
          <ProductDetails slug={slug} />
        </Suspense>
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import './globals.css'
import { NavigationEvents } from './NavigationEvents'

export const metadata: Metadata = {
  title: 'Product Gallery',
  description: 'A simple product gallery',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>
        <NavigationEvents />
        {children}
      </body>
    </html>
  )
}

