  border-radius: 12px;
}

.product-info h1 {
  font-size: 2rem;
}

.product-price {
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0.5rem 0;
}

.product-description {
  color: #666;
  line-height: 1.6;
}

.back-link {
  display: inline-block;
  margin-bottom: 1.5rem;
  color: #666;
  text-decoration: none;
}

.skeleton-image {
  background: #e5e5e5;
}

.skeleton-text {
  height: 1rem;
  background: #e5e5e5;
  border-radius: 4px;
  margin: 0.5rem 1rem;
}

.skeleton-text.short {
  width: 60%;
}

.skeleton-text.large {
  height: 2rem;
  width: 70%;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

@keyframes content-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@keyframes slide-out-left {
  to {
    transform: translateX(-25%);
    opacity: 0;
  }
}

@keyframes slide-in-right {
  from {
    transform: translateX(25%);
    opacity: 0;
  }
}

@keyframes slide-out-right {
  to {
    transform: translateX(25%);
    opacity: 0;
  }
}

@keyframes slide-in-left {
  from {
    transform: translateX(-25%);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .skeleton-image,
  .skeleton-text {
    animation: pulse 1.5s ease-in-out infinite;
  }

  .animate-in {
    animation: content-in 0.35s ease-out both;
  }

  ::view-transition-old(root) {
    animation: 0.3s ease both slide-out-left;
  }

  ::view-transition-new(root) {
    animation: 0.3s ease both slide-in-right;
  }

  html[data-nav-direction='back']::view-transition-old(root) {
    animation-name: slide-out-right;
  }

  html[data-nav-direction='back']::view-transition-new(root) {
    animation-name: slide-in-left;
  }

  ::view-transition-group(*) {
    animation-duration: 0.3s;
  }
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(root),
  ::view-transition-new(root),
  ::view-transition-group(*) {
    animation: none;
  }
}

